def transform(grid):
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
            col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==col:
                        seen.add((a,b)); q.append((a,b))
            comps.append((len(cells),col,cells))
    bg=max(comps,key=lambda z:z[0])[1]
    singles={}
    for n,col,cs in comps:
        if n==1: singles.setdefault(col,[]).extend(cs)
    best=None
    for col,cs in singles.items():
        for kind in (0,1):
            d={}
            for r,c in cs: d.setdefault(c-r if kind==0 else c+r,[]).append((r,c))
            k,v=max(d.items(),key=lambda z:len(z[1]))
            if len(v)>=2 and (best is None or len(v)>best[0]): best=(len(v),col,kind,k,v)
    if best is None: return [row[:] for row in grid]
    _,mark,kind,off,pts=best
