    for r,c in pts: out[r][c]=mark
    vals=[]
    for n,col,cs in comps:
        if col==bg or col==mark or n==1: continue
        proj=[c-r if kind==0 else c+r for r,c in cs]
        near=[x for x in proj if abs(x-off)<=8]
        if near: vals+=near
